fn take(arr: Vec<f32>, indices: Vec<usize>) -> Vec<f32> {
    let mut result = Vec::with_capacity(indices.len());
    for i in indices {
        // Since f32 is Copy, indexing returns a copy of the element.
        result.push(arr[i]);
    }
    result
}

